import {calculatePlateCosts} from './domain.mjs';

// Fully fictional, deterministic demonstration. No network, OCR/model call,
// trained weights, date clock, stock deduction or production data mutation.
const WINDOW=Object.freeze({start:'2026-10-01',end:'2026-10-14',asOf:'2026-10-14'});
const SOURCES=Object.freeze([
  {id:'demo-receipts',title:'Fictional supplier purchase fixtures · 1–14 October 2026',url:null},
  {id:'demo-recipe',title:'Merchant-confirmed recipe assumptions · 100 g chicken per portion',url:null},
  {id:'demo-orders',title:'Fictional completed and cancelled order fixtures · 1–14 October 2026',url:null},
  {id:'current-service',title:'Current browser demo orders and mapped recipes · separate service context',url:null},
  {id:'foodsafety',title:'FoodSafety.gov · Cold Food Storage Chart',url:'https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts'},
  {id:'who',title:'WHO · Five keys to safer food',url:'https://www.who.int/activities/promoting-safe-food-handling/five-key-to-safer-food/'},
]);
const clone=value=>structuredClone(value);
const sources=ids=>clone(SOURCES.filter(source=>ids.includes(source.id)));
const money=cents=>`THB ${(cents/100).toFixed(2)}`;
function valid(state){if(!state||state.schemaVersion!==1||state.simulation!==true||typeof state.receiptConfirmed!=='boolean'||![80,100,120].includes(state.demandPercent)||!['chilled','unknown'].includes(state.storage))throw Error('Use a valid isolated AI demonstration state.');return state;}
function thaiReceiptDate(raw){const [day,month,buddhistYear]=raw.split('/').map(Number);return `${buddhistYear-543}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}
function fixtures(){
  const receipt=(id,date,quantityG,costCents,requiresReview=false)=>({id,date,ingredient:'Chicken',nameTh:'เนื้อไก่',quantityG,costCents,source:'fictional',requiresReview});
  const sampleReceipts=[receipt('purchase-01','2026-10-01',4000,40000),receipt('purchase-03','2026-10-03',4000,40000),receipt('purchase-05','2026-10-05',4000,40000),receipt('purchase-08','2026-10-08',4000,36000),receipt('purchase-10','2026-10-10',4000,36000),receipt('purchase-13','2026-10-13',2000,18000,true)];
  const days=[...Array(14)].map((_,index)=>`2026-10-${String(index+1).padStart(2,'0')}`),offline=[8,9,10,8,10,12,13,9,10,10,11,12,13,15],online=[4,5,4,5,4,5,3,5,5,6,6,6,6,6],sampleOrders=[];
  days.forEach((date,index)=>{for(const channel of ['offline','online'])sampleOrders.push({id:`completed-${date}-${channel}`,date,channel,status:'served',quantity:(channel==='offline'?offline:online)[index],unitPriceCents:channel==='offline'?6500:8500,source:'fictional'});});
  for(const [date,channel,quantity] of [['2026-10-04','offline',2],['2026-10-06','online',2],['2026-10-10','offline',3],['2026-10-12','online',3]])sampleOrders.push({id:`cancelled-${date}-${channel}`,date,channel,status:'cancelled',quantity,unitPriceCents:channel==='offline'?6500:8500,source:'fictional'});
  return {sampleReceipts,sampleOrders};
}
export function createAiDemoState(){return {schemaVersion:1,simulation:true,window:clone(WINDOW),receiptConfirmed:false,demandPercent:100,storage:'unknown',...fixtures()};}
export function updateAiDemo(state,{action,value}={}){
  valid(state);const next=clone(state);
  if(action==='confirm-receipt'){if(value!==undefined&&typeof value!=='boolean')throw Error('Receipt confirmation must be true or false.');next.receiptConfirmed=value??true;}
  else if(action==='demand'){if(![80,100,120].includes(value))throw Error('Choose demand of 80, 100 or 120 percent.');next.demandPercent=value;}
  else if(action==='storage'){if(!['chilled','unknown'].includes(value))throw Error('Choose chilled storage or unknown storage.');next.storage=value;}
  else throw Error('Unknown AI demo action.');
  return next;
}
function summarizeWeek(state,index){
  const start=index===0?'2026-10-01':'2026-10-08',end=index===0?'2026-10-07':'2026-10-14';
  // Analysis always uses the canonical fixed fixtures, not caller-injected orders.
  const {sampleReceipts,sampleOrders}=fixtures(),orders=sampleOrders.filter(item=>item.date>=start&&item.date<=end),completed=orders.filter(item=>item.status==='served'),cancelled=orders.filter(item=>item.status==='cancelled');
  const receipts=sampleReceipts.filter(item=>item.date>=start&&item.date<=end),approved=receipts.filter(item=>!item.requiresReview||state.receiptConfirmed),pending=receipts.filter(item=>item.requiresReview&&!state.receiptConfirmed);
  const completedPortions=completed.reduce((sum,item)=>sum+item.quantity,0),offlinePortions=completed.filter(item=>item.channel==='offline').reduce((sum,item)=>sum+item.quantity,0),onlinePortions=completedPortions-offlinePortions;
  const orderValueCents=completed.reduce((sum,item)=>sum+item.quantity*item.unitPriceCents,0),feeCents=completed.filter(item=>item.channel==='online').reduce((sum,item)=>sum+item.quantity*2550,0);
  const costKnown=index===0||state.receiptConfirmed,chickenCentsPerPortion=index===0?1000:900;
  const chickenCostCents=costKnown?completedPortions*chickenCentsPerPortion:null,otherIngredientCostCents=completedPortions*900,recipeCogsCents=costKnown?chickenCostCents+otherIngredientCostCents:null,packagingCents=completedPortions*300,otherVariableCents=completedPortions*200;
  return {id:`week-${index+1}`,label:`Week ${index+1}`,labelTh:`สัปดาห์ ${index+1}`,start,end,completedPortions,cancelledPortions:cancelled.reduce((sum,item)=>sum+item.quantity,0),offlinePortions,onlinePortions,purchaseCents:approved.reduce((sum,item)=>sum+item.costCents,0),purchasedG:approved.reduce((sum,item)=>sum+item.quantityG,0),pendingPurchaseCents:pending.reduce((sum,item)=>sum+item.costCents,0),pendingPurchasedG:pending.reduce((sum,item)=>sum+item.quantityG,0),chickenUsedG:completedPortions*100,chickenCostCents,otherIngredientCostCents,recipeCogsCents,packagingCents,otherVariableCents,feeCents,onlineFeeBps:3000,offlineFeeBps:0,orderValueCents,contributionCents:recipeCogsCents===null?null:orderValueCents-recipeCogsCents-packagingCents-otherVariableCents-feeCents,costKnown};
}
function stockReview(state){
  const general={expiryKnown:false,expiryDate:null,remainingStockG:null,storage:state.storage,daysSincePurchase:1,guideline:{ingredient:'Raw chicken pieces',temperatureMaxC:4,minDays:1,maxDays:2,scope:'General home refrigeration guidance; not a commercial use-by certification.'},sources:sources(['foodsafety','who']),requiresMerchantReview:true};
  if(!state.receiptConfirmed)return {...general,status:'receipt-unconfirmed',reviewOn:null,title:'Confirm the receipt first',titleTh:'ยืนยันใบซื้อก่อน',detail:'The date and ingredient are unconfirmed. No stock reminder is created. A purchase date alone cannot establish expiry or safe condition.',detailTh:'ยังไม่ยืนยันวันที่และวัตถุดิบ จึงไม่สร้างการเตือนตรวจสต็อก วันที่ซื้ออย่างเดียวบอกวันหมดอายุหรือความปลอดภัยไม่ได้'};
  if(state.storage==='unknown')return {...general,status:'storage-unknown',reviewOn:null,title:'Storage conditions needed',titleTh:'ต้องทราบวิธีเก็บก่อน',detail:'Cold-chain history, package use-by instructions and condition are unknown. No stock reminder is created. Check those facts with the merchant; do not infer shelf life from this receipt.',detailTh:'ยังไม่ทราบประวัติอุณหภูมิ คำแนะนำวันควรใช้บนฉลาก และสภาพสินค้า จึงไม่สร้างการเตือนตรวจสต็อก ให้ร้านตรวจข้อมูลก่อน ห้ามอนุมานอายุเก็บจากใบซื้อ'};
  return {...general,status:'review-due',reviewOn:'2026-10-14',title:'Illustrative stock check today',titleTh:'ตัวอย่างการตรวจสต็อกวันนี้',detail:'Assuming continuous refrigeration at 4°C or below, FoodSafety.gov lists 1–2 days for raw chicken. Review the 13 October purchase on 14 October; this is a planning reminder, not an expiry date or permission to use it. Follow the label, condition and actual cold-chain history; any earlier limit takes precedence.',detailTh:'ภายใต้สมมติฐานว่าแช่เย็นต่อเนื่องไม่เกิน 4°C FoodSafety.gov ระบุไก่ดิบ 1–2 วัน ตัวอย่างให้ตรวจของที่ซื้อ 13 ต.ค. ในวันที่ 14 ต.ค. เป็นการเตือนตรวจ ไม่ใช่วันหมดอายุหรือการรับรองให้ใช้ ต้องยึดฉลาก สภาพจริง และประวัติอุณหภูมิ โดยเงื่อนไขที่สั้นกว่าต้องมาก่อน'};
}
export function summarizeAiDemo(state,{copilotState}={}){
  valid(state);const weeklyMetrics=[summarizeWeek(state,0),summarizeWeek(state,1)],[first,second]=weeklyMetrics;
  const plateNumerator=(second.completedPortions*65+first.completedPortions*35)*state.demandPercent,plates=Math.min(24,Math.ceil(plateNumerator/70000));
  const receipt={id:'purchase-13',rawText:'ใบซื้อวัตถุดิบจำลอง\nร้านวัตถุดิบซอย\nวันที่ 13/10/2569\nเนื้อไก่ 2 กก. x 90.00 = 180.00 บาท\nรวม 180.00 บาท',dateRaw:'13/10/2569',dateISO:thaiReceiptDate('13/10/2569'),ingredient:'Chicken',nameTh:'เนื้อไก่',purchaseQuantity:2,purchaseUnit:'kg',quantityG:2000,purchaseCostCents:18000,unitCostCentsPerKg:9000,unitCostCentsPerG:9,portionG:100,portionCostCents:900,confirmed:state.receiptConfirmed,source:'fictional',ocrMode:'simulated',storageKnown:state.storage==='chilled'};
  const difference=second.contributionCents===null?null:second.contributionCents-first.contributionCents;
  const currentService=copilotState?{...calculatePlateCosts(copilotState).totals,basis:'Current copilot service records, separate from the fixed 1–14 October fictional comparison. Includes open and served orders, excludes cancelled orders; contribution uses current mapped recipes.',basisTh:'ข้อมูลรอบบริการ Copilot ปัจจุบัน แยกจากตัวอย่างวันที่ 1–14 ต.ค. รวมออเดอร์ที่ยังเปิดและเสิร์ฟแล้ว ไม่รวมรายการยกเลิก ใช้ต้นทุนสูตรที่กำหนดไว้',simulation:true}:null;
  return {simulation:true,mode:'deterministic-demo',window:clone(WINDOW),receipt,
    stages:[{id:'receipt',status:'complete',label:'Read sample receipt',labelTh:'อ่านใบซื้อตัวอย่าง'},{id:'normalize',status:state.receiptConfirmed?'complete':'review',label:'Normalize and confirm',labelTh:'แปลงหน่วยและยืนยัน'},{id:'analysis',status:state.receiptConfirmed?'complete':'pending',label:'Compare two weeks',labelTh:'เปรียบเทียบสองสัปดาห์'},{id:'adapt',status:'illustrative',label:'Adjust the next prep plan',labelTh:'ปรับแผนเตรียมครั้งถัดไป'}],
    weeklyMetrics,comparison:{contributionChangeCents:difference,contributionChangePercent:difference===null?null:Math.round(difference*10000/first.contributionCents)/100,purchaseChangeCents:second.purchaseCents-first.purchaseCents,chickenUsageChangeG:second.chickenUsedG-first.chickenUsedG,completedPortionChange:second.completedPortions-first.completedPortions,complete:state.receiptConfirmed},
    suggestedPrep:{plates,chickenG:plates*100,demandPercent:state.demandPercent,capacityPlates:24,baselineDailyPortions:Math.round((first.completedPortions+second.completedPortions)*100/14)/100,recentDailyPortions:Math.round(second.completedPortions*100/7)/100,earlierDailyPortions:Math.round(first.completedPortions*100/7)/100,method:'Illustrative rule: 65% recent-week daily portions + 35% earlier-week daily portions; multiply by the selected demand scenario, round up, and cap at 24 portions. This is not a forecast or a trained model.',methodTh:'กฎตัวอย่าง: เฉลี่ยต่อวันสัปดาห์ล่าสุด 65% กับสัปดาห์ก่อน 35% คูณสถานการณ์ความต้องการที่เลือก ปัดขึ้นและจำกัด 24 จาน ไม่ใช่การพยากรณ์หรือโมเดลที่ฝึกแล้ว',inventoryKnown:false,reorderQuantityG:null,reviewNote:'A target for merchant review only. Check bookings, actual usable stock, storage safety and staffing before preparing or buying.',reviewNoteTh:'เป็นเป้าหมายให้ร้านพิจารณา ต้องตรวจยอดจอง สต็อกที่ใช้ได้จริง ความปลอดภัยในการเก็บ และกำลังคนก่อนเตรียมหรือซื้อ'},
    stockReview:stockReview(state),currentService,sampleReceipts:fixtures().sampleReceipts.map(item=>({...item,confirmed:!item.requiresReview||state.receiptConfirmed})),sources:clone(SOURCES),
    assumptions:[
      'All receipts, orders, quantities and business outcomes in the fixed window are fictional. No OCR, model, API or weight training runs.',
      'The 14-day window is for business comparison, never chicken shelf life. Purchase dates cannot determine actual expiry.',
      'Purchase spend covers chicken receipts only. Recipe COGS estimates chicken consumed plus other mapped ingredients; it is not purchase spend or an inventory reconciliation.',
      'Recipe: 100 g chicken and THB 9 other ingredients per portion; THB 3 packaging and THB 2 other variable cost. Chicken cost assumes THB 100/kg in week 1 and THB 90/kg in week 2 after review.',
      'Store price THB 65; online price THB 85 with assumed 30% effective fee. Store platform fee is zero. These are scenario values, not universal Grab charges.',
      'Cancelled portions are excluded from revenue and recipe consumption. Cancellation waste is unknown and excluded; actual prepared waste must be entered separately.',
      'Contribution is before fixed overhead, tax and unentered costs, not net profit, cash collected or evidence of AI-caused uplift.',
      'No remaining-stock or reorder claim: opening stock, waste, transfers and physical count are unknown. Current copilot service records are shown separately, never added to the dated fixture.'
    ]};
}
export function answerAiDemo(question,state,language='en',{copilotState}={}){
  valid(state);if(typeof question!=='string'||!question.trim()||question.length>1000)throw Error('Ask a question of 1 to 1,000 characters.');if(!['en','th'].includes(language))throw Error('Choose English or Thai.');
  const q=question.trim().toLowerCase(),s=summarizeAiDemo(state,{copilotState}),th=language==='th';let topic='scope',content,used=[];
  if(/expire|expiry|shelf|safe|spoil|storage|chill|fridge|หมดอายุ|ปลอดภัย|แช่|เก็บ|บูด/.test(q)){
    topic='stock-review';used=['foodsafety','who'];const review=s.stockReview;
    content=th?`${review.titleTh}: ${review.detailTh} ช่วง 14 วันเป็นช่วงวิเคราะห์ธุรกิจ ไม่ใช่อายุเก็บไก่ และเราไม่ทราบสต็อกคงเหลือจริงหรือวันหมดอายุจริง`:`${review.title}: ${review.detail} The 14 days are a business-analysis window, not chicken shelf life. Actual remaining stock and expiry are unknown.`;
  }else if(/current service|current queue|orders today|today.s orders|qr|ออเดอร์ปัจจุบัน|คิวปัจจุบัน|ออเดอร์วันนี้/.test(q)&&!/prep|demand|prepare|forecast|tomorrow|เตรียม|พรุ่งนี้|ต้องการ|พยากรณ์/.test(q)){
    topic='current-service';used=['current-service'];const c=s.currentService;
    content=!c?(th?'ยังไม่มีข้อมูลรอบบริการปัจจุบันที่ส่งมาให้เดโมนี้ จึงไม่อนุมานจำนวนออเดอร์หรือกำไรจากคิว ตัวอย่าง 14 วันเป็นคนละชุดข้อมูล':'No current-service context was supplied. I cannot infer queue counts or margin from it. The fixed 14-day example is a different dataset.'):(th?`รอบบริการเดโมปัจจุบันมี ${c.quantity} รายการ: เสิร์ฟแล้ว ${c.servedQuantity} และยังเปิด ${c.openQuantity} มูลค่าออเดอร์ ${money(c.orderValueCents)} กำไรส่วนเกินประมาณ ${c.contributionCents===null?'ยังคำนวณไม่ได้เพราะขาดต้นทุนหรือค่าธรรมเนียม':money(c.contributionCents)} ใช้สูตรปัจจุบัน ไม่ใช่ยอดรับชำระและไม่ถูกบวกเข้าตัวอย่าง 1–14 ต.ค.`:`Current demo service: ${c.quantity} items — ${c.servedQuantity} served and ${c.openQuantity} open. Order value ${money(c.orderValueCents)}; estimated contribution ${c.contributionCents===null?'unknown because recipe costs or online fees are missing':money(c.contributionCents)}. These use current recipes, are not collected payments, and are not added to the 1–14 October fixture.`);
  }else if(/receipt|ocr|normaliz|kilogram|\bkg\b|ใบซื้อ|ใบเสร็จ|แปลง|กิโล|หน่วย/.test(q)){
    topic='receipt';used=['demo-receipts','demo-recipe'];content=th?`ใบซื้อจำลองวันที่ 13/10/2569 แปลงเป็น 2026-10-13 ไก่ 2 กก. = 2,000 กรัม ราคา THB 180.00 คิดเป็น THB 90.00/กก. สูตรที่ร้านกำหนด 100 กรัมต่อจานจึงมีต้นทุนไก่ THB 9.00 ${state.receiptConfirmed?'ยืนยันตัวอย่างแล้ว':'ยังรอยืนยัน จึงยังไม่สรุปต้นทุนและกำไรส่วนเกินสัปดาห์ที่ 2'} ปริมาณใช้ได้และสูตรต้องให้ร้านยืนยัน ไม่ได้อนุมานจาก OCR`:`The simulated receipt date 13/10/2569 normalizes to 2026-10-13. Chicken: 2 kg = 2,000 g for THB 180.00, or THB 90.00/kg. The merchant-defined 100 g portion therefore uses THB 9.00 of chicken. ${state.receiptConfirmed?'The sample is confirmed.':'Confirmation is pending, so week 2 recipe cost and contribution remain unknown.'} Usable quantity and recipe portions require merchant confirmation; OCR does not infer them.`;
  }else if(/prep|demand|prepare|forecast|tomorrow|เตรียม|พรุ่งนี้|ต้องการ|พยากรณ์/.test(q)){
    topic='prep';used=['demo-orders','demo-recipe'];const p=s.suggestedPrep;content=th?`สถานการณ์ความต้องการ ${p.demandPercent}% ให้เป้าหมายตัวอย่าง ${p.plates} จาน หรือไก่ ${p.chickenG} กรัม ${p.methodTh} ${p.reviewNoteTh} ไม่ทราบสต็อกจริงจึงยังระบุปริมาณสั่งซื้อไม่ได้`:`At the ${p.demandPercent}% demand scenario, the illustrative next-service target is ${p.plates} portions, using ${p.chickenG} g of chicken. ${p.method} ${p.reviewNote} Actual inventory is unknown, so no reorder quantity is calculated.`;
  }else if(/week|cost|profit|margin|contribution|purchase|revenue|กำไร|ต้นทุน|สัปดาห์|ยอดขาย|รายได้|ซื้อ/.test(q)){
    topic='weekly-analysis';used=['demo-receipts','demo-recipe','demo-orders'];const [a,b]=s.weeklyMetrics;
    content=!state.receiptConfirmed?(th?`ยืนยันใบซื้อตัวอย่างก่อน: สัปดาห์ที่ 2 มีใบซื้อไก่ที่ยืนยันแล้ว ${money(b.purchaseCents)} และรอยืนยัน ${money(b.pendingPurchaseCents)} ต้นทุนสูตรกับกำไรส่วนเกินยังไม่ทราบ การซื้อวัตถุดิบไม่เท่ากับต้นทุนที่ใช้ขาย`:`Confirm the sample receipt first. Week 2 has ${money(b.purchaseCents)} in reviewed chicken purchases and ${money(b.pendingPurchaseCents)} pending. Recipe COGS and contribution remain unknown. Buying ingredients is not the same as consuming them in sold portions.`):(th?`ตัวอย่างสัปดาห์ 1 → 2: ซื้อไก่ ${money(a.purchaseCents)} → ${money(b.purchaseCents)} แต่ไก่ที่ใช้ตามสูตร ${money(a.chickenCostCents)} → ${money(b.chickenCostCents)} เพราะขาย ${a.completedPortions} → ${b.completedPortions} จาน กำไรส่วนเกิน ${money(a.contributionCents)} → ${money(b.contributionCents)} หลังหักวัตถุดิบ บรรจุภัณฑ์ ต้นทุนผันแปรที่ระบุและค่าธรรมเนียมออนไลน์สมมติ 30% ไม่รวมยกเลิก ${a.cancelledPortions} / ${b.cancelledPortions} จาน ไม่ใช่กำไรสุทธิ ยอดรับชำระ หรือหลักฐานว่า AI ทำให้กำไรเพิ่ม`:`Fictional week 1 → 2: chicken purchases ${money(a.purchaseCents)} → ${money(b.purchaseCents)}, but recipe-implied chicken consumed ${money(a.chickenCostCents)} → ${money(b.chickenCostCents)} as completed portions rise ${a.completedPortions} → ${b.completedPortions}. Contribution is ${money(a.contributionCents)} → ${money(b.contributionCents)} after mapped ingredients, packaging, entered variable costs and the assumed 30% online fee. ${a.cancelledPortions} / ${b.cancelledPortions} cancelled portions are excluded. This is not net profit, collected cash or evidence that AI caused an improvement.`);
  }else if(/model|gemini|llama|train|api|โมเดล|ฝึก|เอไอ|\bai\b/.test(q)){
    topic='simulation';content=th?'นี่คือคำตอบเดโมจากกฎและข้อมูลตัวอย่างตายตัว ไม่มีการเรียก Gemini, Llama หรือ API และไม่ได้ฝึกน้ำหนักโมเดล การเปลี่ยนแผนเป็นการปรับสูตรคำนวณตามสถานการณ์ที่เลือก':'This is a deterministic demonstration using fixed fictional evidence and rules. No Gemini, Llama or API is called, and no model weights are trained. Plan changes come from an explicit scenario calculation.';
  }else content=th?'เดโมนี้ตอบได้เฉพาะใบซื้อไก่ตัวอย่าง ต้นทุนต่อจาน การเปรียบเทียบ 1–14 ต.ค. แผนเตรียม และเงื่อนไขตรวจสต็อก ยังไม่มีหลักฐานเพื่อตอบคำถามนี้ ลองถามว่า “ทำไมยอดซื้อต่างจากต้นทุนที่ใช้ขาย?”':'This demo can explain the sample chicken receipt, plate cost, 1–14 October comparison, prep rule and stock-review conditions. It has no evidence to answer that question. Try “Why are purchases different from recipe COGS?”';
  return {id:`ai-demo-${topic}-${state.receiptConfirmed?1:0}-${state.demandPercent}-${state.storage}`,role:'assistant',content,simulation:true,mode:'deterministic-demo',topic,sources:sources(used)};
}
